    "about_text": "Sway Digital Lab एक स्वतंत्र डिजिटल स्टूडियो है जो सरल, उपयोगी और सोच-समझकर बनाए गए डिजिटल उत्पादों पर ध्यान केंद्रित करता है। हम नए विचारों को तलाशते हैं, ऐप्स बनाते हैं और अवधारणाओं को ऐसे टूल्स में बदलते हैं जो रोज़मर्रा की ज़िंदगी को थोड़ा आसान बना सकें।",
