    "apps_title": "विचार जो उत्पाद बनते हैं।",
    "apps_text": "Sway Digital Lab द्वारा बनाए गए डिजिटल उत्पादों को देखें।",
    "featured_label": "प्रमुख ऐप",
    "featured_tagline": "7,000+ शब्दों (CEFR A1–C2), 11 विषयगत संग्रहों, 38 सचित्र कहानियों, होम स्क्रीन विजेट, AI बुक स्कैनर, 5 अभ्यास मोड और हैंड्स-फ़्री ऑडियो के साथ एक संपूर्ण अंग्रेज़ी वोकैबुलरी बिल्डर।",
    "screenshot_1_alt": "English Breakfast ऐप, आज का शब्द स्क्रीन: तीन हरे बटन (शुरू करें, श्रेणी चुनें और पसंदीदा दोहराएं) और एक गोल्डन कार्ड जिस पर \"skiing\" शब्द, उच्चारण और Elementary लेवल टैग है।",
    "screenshot_2_alt": "English Breakfast ऐप, फ़्लैशकार्ड स्क्रीन: कार्ड, क्विज़, जोड़े और टेस्ट टैब, \"In learning 1/10\" प्रगति लेबल, \"president\" शब्द वाला कार्ड, स्पीकर व पसंदीदा बटन, और नीचे सीखें तथा जानते हैं बटन।",
    "screenshot_3_alt": "English Breakfast ऐप, श्रेणी चुनें सूची: Elementary वोकैबुलरी (2,451 शब्द), अनियमित क्रियाएं (149), फ़्रेज़ल पैटर्न (437), Intermediate वोकैबुलरी (2,116) और Advanced वोकैबुलरी (1,576)।",
    "screenshot_4_alt": "English Breakfast ऐप, काउंटडाउन टाइमर के साथ साप्ताहिक लीग लीडरबोर्ड: 6,184 XP के साथ Nick Lip के नेतृत्व में शीर्ष चार पोडियम, और अवतार व XP स्कोर के साथ खिलाड़ियों की सूची।",
    "why_title": "English Breakfast ही क्यों",
    "why_desc": "English Breakfast अंग्रेज़ी शब्द सीखने को एक आसान दैनिक आदत में बदल देता है। 7,000+ आवृत्ति-आधारित शब्द, गोल्डन कार्ड होम स्क्रीन विजेट, 38 सचित्र कहानियाँ, 5-चरणीय मेमोरी वर्कफ़्लो, AI बुक स्कैनर और हैंड्स-फ़्री ऑडियो — बिना किसी हार्ट लिमिट के 100% मुफ़्त।",
    "benefit_audio_title": "हेडफ़ोन में हैंड्स-फ़्री ऑडियो",
    "benefit_audio_short": "स्क्रीन को छुए बिना टहलते, दौड़ते या यात्रा करते समय शब्द सीखें।",
    "benefit_audio_p1": "स्मार्ट रिकॉल पॉज़ के साथ बैकग्राउंड में हैंड्स-फ़्री ऑडियो प्लेबैक",
    "benefit_audio_p2": "पहले आपकी मातृभाषा में अनुवाद, सोचने का विराम, फिर स्पष्ट अंग्रेज़ी उच्चारण",
    "benefit_audio_p3": "फ़ोन की स्क्रीन लॉक होने पर भी बैकग्राउंड में सुचारू रूप से चलता है",
    "benefit_audio_p4": "न्यूरल स्टूडियो ब्रिटिश (UK) और अमेरिकन (US) उच्चारण",
    "benefit_cards_title": "3D फ़्लैशकार्ड, वर्ड ब्लॉक्स और 5 मोड",
    "benefit_cards_short": "5 रोचक प्रशिक्षण चरणों के साथ अनुकूली स्पेस्ड रिपीटिशन।",
    "benefit_cards_p1": "स्वाइप और IPA फ़ोनेटिक्स के साथ इंटरैक्टिव 3D फ़्लिप फ़्लैशकार्ड",
    "benefit_cards_p2": "कठिन शब्दों को आसानी से सीखने के लिए नया वर्ड ब्लॉक्स पज़ल चरण",
    "benefit_cards_p3": "याद करने की गति बढ़ाने के लिए तेज़ टाइम्ड क्विज़ और पेयर मैचिंग",
    "benefit_cards_p4": "स्पेलिंग स्प्रिंट और स्मार्ट राउंड आर्किटेक्ट जो कठिन शब्दों को 100% तक दोहराता है",
    "benefit_vocab_title": "7,000+ शब्द, CEFR और 11 संग्रह",
    "benefit_vocab_short": "ज़िफ़ के नियम (Zipf's law) के अनुसार Elementary A1 से Advanced C2 तक क्रमबद्ध।",
    "benefit_vocab_p1": "7,000+ चुने हुए शब्द — पहले 1,000 शब्द रोज़मर्रा की बातचीत का 85% हिस्सा कवर करते हैं",
    "benefit_vocab_p2": "व्याख्या के साथ 187 IT और टेक शब्दों सहित 11 विषयगत संग्रह",
    "benefit_vocab_p3": "150 लोकप्रिय मुहावरे और कहावतें तथा तीनों रूपों में 149 अनियमित क्रियाएं",
    "benefit_vocab_p4": "स्वाभाविक बोलचाल के प्रवाह के लिए संवादात्मक फ़्रेज़ल पैटर्न",
